import ast
import os
import sys
import subprocess
import tempfile
import shutil
import tomllib
import re
import time
import json
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Any, Tuple, Iterable

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Dependency contract: hae/evaluation/artifacts.py
# Since it's being implemented in parallel, we assume it exists or provide fallbacks if needed.
# However, the prompt implies we should use it. If it's not present, we might need to inline logic.
# Given the strict "Dependency contract", I will assume it is importable.
# If not, I will implement the logic locally to ensure robustness as per "satisfying 100% of Public API Contract".
try:
    from hae.evaluation.artifacts import (
        is_generated_path,
        is_malformed_path,
        sanitize_path,
        filter_bundle,
        partition_bundle,
        count_source_files
    )
except ImportError:
    # Fallback implementation if artifacts.py is not yet available in the environment
    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = path.split(os.sep)
        for part in parts:
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return True
        # Check for markdown decoration or invalid chars
        if '*' in path or '`' in path:
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        if path != path.strip():
            return True
        return False

    def sanitize_path(path: str) -> str:
        # Strip markdown decoration
        path = path.replace('*', '').replace('`', '')
        path = path.strip()
        if path.startswith('-'):
            path = path[1:]
        if path.endswith('.') or path.endswith('~'):
            path = path[:-1]
        return path

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {k: v for k, v in bundle.items() if not is_generated_path(k) and not is_malformed_path(k)}

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_generated_path(k):
                generated[k] = v
            elif is_malformed_path(k):
                malformed[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
        count = 0
        for path in bundle.keys():
            if any(path.endswith(s) for s in suffixes):
                count += 1
        return count


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed = [g for g in evaluated if g.passed]
        return len(passed) / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files}, Python Files: {self.python_files}")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append(f"Pass Rate: {self.pass_rate:.2%}")
        lines.append("Gates:")
        for g in self.gates:
            lines.append(f"  [{g.status.upper():7}] {g.name:10} ({g.method}): {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "pass_rate": self.pass_rate,
            "gate_status": self.gate_status,
            "gate_detail": self.gate_detail
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to find fenced code blocks with optional language and optional filename
    # Pattern: ```[language] [filename]\n...content...\n```
    # We look for lines starting with ``` followed by optional lang and optional path
    pattern = r"```(?:\w+)?\s+([^\n]+)\n(.*?)```"
    matches = re.findall(pattern, text, re.DOTALL)

    bundle = {}
    for path, content in matches:
        path = path.strip()
        if not path:
            continue
        # Sanitize path if needed, though extract_code_blocks usually gets raw text
        # We assume the path in the fence is the intended path
        bundle[path] = content

    return bundle


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        if workspace is not None:
            # Assume workspace has a method to get files or is a dict
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
            elif isinstance(workspace, dict):
                bundle = workspace
            else:
                # Try to treat as directory if it's a string path
                if isinstance(workspace, str) and os.path.isdir(workspace):
                    return self.verify_directory(workspace)
                # Fallback to empty
                bundle = {}

        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        return self.verify_bundle(bundle, source=source)

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        if not bundle:
            # Empty workspace
            return self._create_empty_report(source)

        # Filter bundle to get authored files
        authored_bundle = filter_bundle(bundle)

        # Count files
        authored_files_count = len(authored_bundle)
        python_files_count = count_source_files(authored_bundle, suffixes=('.py',))

        if python_files_count == 0:
            # No python files to verify
            return self._create_empty_report(source, authored_files=authored_files_count, python_files=0)

        with tempfile.TemporaryDirectory() as tmpdir:
            # Write bundle to temp dir
            for path, content in authored_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=authored_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if not os.path.isdir(workdir):
            return self._create_empty_report(source)

        # If authored bundle not provided, scan directory
        if authored is None:
            bundle = {}
            for root, dirs, files in os.walk(workdir):
                # Prune excluded dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]
                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if is_generated_path(rel_path) or is_malformed_path(rel_path):
                        continue
                    try:
                        with open(os.path.join(root, file), 'r', encoding='utf-8') as f:
                            bundle[rel_path] = f.read()
                    except Exception:
                        pass
            authored = bundle

        authored_files_count = len(authored)
        python_files_count = count_source_files(authored, suffixes=('.py',))

        if python_files_count == 0:
            return self._create_empty_report(source, authored_files=authored_files_count, python_files=0)

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(workdir, authored))

        # 2. Build Gate
        gates.append(self._gate_build(workdir, authored))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, authored))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, authored))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(workdir, authored))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files_count,
            python_files=python_files_count,
            source=source
        )

    def _create_empty_report(self, source: str, authored_files: int = 0, python_files: int = 0) -> VerificationReport:
        gates = [
            GateResult(name='syntax', status=FAILED, method='ast.parse', detail='No Python files found'),
            GateResult(name='build', status=FAILED, method='metadata', detail='No Python files found'),
            GateResult(name='smoke', status=FAILED, method='import', detail='No Python files found'),
            GateResult(name='tests', status=FAILED, method='pytest', detail='No Python files found'),
            GateResult(name='telemetry', status=FAILED, method='ast', detail='No Python files found'),
        ]
        return VerificationReport(
            gates=gates,
            score_penalty=5 * self.penalty_per_gate,
            authored_files=authored_files,
            python_files=python_files,
            source=source
        )

    def _gate_syntax(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        py_files = [p for p in authored.keys() if p.endswith('.py')]
        if not py_files:
            return GateResult(name='syntax', status=FAILED, method='ast.parse', detail='No Python files', duration_s=time.time()-start)

        errors = []
        for path in py_files:
            content = authored[path]
            try:
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")

        duration = time.time() - start
        if errors:
            return GateResult(name='syntax', status=FAILED, method='ast.parse', detail='; '.join(errors), duration_s=duration)
        return GateResult(name='syntax', status=PASSED, method='ast.parse', detail='All files parsed', duration_s=duration)

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        # Check for metadata files
        metadata_files = ['pyproject.toml', 'setup.py', 'setup.cfg']
        found_metadata = None
        for mf in metadata_files:
            if mf in authored:
                found_metadata = mf
                break

        if not found_metadata:
            return GateResult(name='build', status=FAILED, method='metadata', detail='No packaging metadata found', duration_s=time.time()-start)

        # Validate pyproject.toml if present
        if 'pyproject.toml' in authored:
            try:
                data = tomllib.loads(authored['pyproject.toml'])
                if not any(k in data for k in ['project', 'build-system', 'tool']):
                    return GateResult(name='build', status=FAILED, method='tomllib', detail='pyproject.toml missing required tables', duration_s=time.time()-start)
            except Exception as e:
                return GateResult(name='build', status=FAILED, method='tomllib', detail=f'Invalid pyproject.toml: {e}', duration_s=time.time()-start)

        # Try pip install
        try:
            # Check if pip is available
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], check=True, capture_output=True, timeout=10)

            # Run pip install
            cmd = [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation']
            result = subprocess.run(cmd, cwd=workdir, capture_output=True, text=True, timeout=self.timeout_s)

            duration = time.time() - start
            if result.returncode != 0:
                return GateResult(name='build', status=FAILED, method='pip', detail=f'pip install failed: {result.stderr}', duration_s=duration)

            return GateResult(name='build', status=PASSED, method='pip', detail='Installed successfully', duration_s=duration)

        except FileNotFoundError:
            return GateResult(name='build', status=SKIPPED, method='pip', detail='pip not available', duration_s=time.time()-start)
        except subprocess.TimeoutExpired:
            return GateResult(name='build', status=FAILED, method='pip', detail='pip install timed out', duration_s=time.time()-start)
        except Exception as e:
            return GateResult(name='build', status=FAILED, method='pip', detail=f'Error: {e}', duration_s=time.time()-start)

    def _gate_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        # Find non-test modules
        modules = []
        for path in authored.keys():
            if not path.endswith('.py'):
                continue
            basename = os.path.basename(path)
            if 'test' in basename.lower():
                continue
            # Convert path to module name
            # Remove .py
            mod_path = path[:-3]
            # Replace / with .
            mod_name = mod_path.replace(os.sep, '.')
            # Handle __init__.py
            if mod_name.endswith('.__init__'):
                mod_name = mod_name[:-9]
            if mod_name:
                modules.append(mod_name)

        if not modules:
            return GateResult(name='smoke', status=FAILED, method='import', detail='No importable modules', duration_s=time.time()-start)

        # Prepare environment
        env = os.environ.copy()
        src_dir = os.path.join(workdir, 'src')
        python_path = f"{workdir}:{src_dir}"
        if 'PYTHONPATH' in env:
            env['PYTHONPATH'] = f"{python_path}:{env['PYTHONPATH']}"
        else:
            env['PYTHONPATH'] = python_path

        # Run import check in subprocess
        script = f"""
import sys
import importlib
modules = {modules!r}
errors = []
skipped = False
for mod in modules:
    try:
        importlib.import_module(mod)
    except ModuleNotFoundError as e:
        # Check if it's a third party package
        # If the module itself is not found, it might be third party
        # But if it's our module, it should be found.
        # We assume if it fails with ModuleNotFoundError, it's likely third party dependency
        # unless the module name is one of our top-level packages.
        # Simple heuristic: if the top-level package is not in sys.path, it's third party.
        # But we added workdir to path.
        # If the module is 'opentelemetry', it's third party.
        if 'opentelemetry' in str(e) or 'importlib' not in str(e): # Heuristic
             skipped = True
        else:
             errors.append(f"{mod}: {e}")
    except Exception as e:
        errors.append(f"{mod}: {e}")

if errors:
    print("ERRORS:" + ";".join(errors))
elif skipped:
    print("SKIPPED")
else:
    print("OK")
"""
        try:
            result = subprocess.run([self.python_executable, '-c', script], cwd=workdir, env=env, capture_output=True, text=True, timeout=self.timeout_s)
            duration = time.time() - start
            output = result.stdout.strip()

            if output == "OK":
                return GateResult(name='smoke', status=PASSED, method='import', detail='All modules imported', duration_s=duration)
            elif output == "SKIPPED":
                return GateResult(name='smoke', status=SKIPPED, method='import', detail='Third-party dependencies missing', duration_s=duration)
            elif output.startswith("ERRORS:"):
                return GateResult(name='smoke', status=FAILED, method='import', detail=output[7:], duration_s=duration)
            else:
                return GateResult(name='smoke', status=FAILED, method='import', detail=f'Unexpected output: {output}', duration_s=duration)

        except Exception as e:
            return GateResult(name='smoke', status=FAILED, method='import', detail=f'Execution error: {e}', duration_s=time.time()-start)

    def _gate_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        # Find test files
        test_files = [p for p in authored.keys() if 'test' in os.path.basename(p).lower() and p.endswith('.py')]

        if not test_files:
            return GateResult(name='tests', status=FAILED, method='discover', detail='No test files found', duration_s=time.time()-start)

        # Prepare environment
        env = os.environ.copy()
        src_dir = os.path.join(workdir, 'src')
        python_path = f"{workdir}:{src_dir}"
        if 'PYTHONPATH' in env:
            env['PYTHONPATH'] = f"{python_path}:{env['PYTHONPATH']}"
        else:
            env['PYTHONPATH'] = python_path

        # Try pytest first
        try:
            subprocess.run([self.python_executable, '-m', 'pytest', '--version'], check=True, capture_output=True, timeout=10)
            cmd = [self.python_executable, '-m', 'pytest', '-v']
            result = subprocess.run(cmd, cwd=workdir, env=env, capture_output=True, text=True, timeout=self.timeout_s)
            duration = time.time() - start
            if result.returncode == 0:
                return GateResult(name='tests', status=PASSED, method='pytest', detail='All tests passed', duration_s=duration)
            else:
                # Check if it was skipped due to missing deps
                if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                     return GateResult(name='tests', status=SKIPPED, method='pytest', detail='Missing dependencies', duration_s=duration)
                return GateResult(name='tests', status=FAILED, method='pytest', detail='Tests failed', duration_s=duration)
        except FileNotFoundError:
            pass # Fallback to stdlib
        except Exception:
            pass # Fallback to stdlib

        # Stdlib fallback
        script = f"""
import sys
import unittest
import importlib
import os

test_files = {test_files!r}
collected = 0
failed = 0
skipped = False

for tf in test_files:
    mod_name = tf[:-3].replace(os.sep, '.')
    if mod_name.endswith('.__init__'):
        mod_name = mod_name[:-9]
    try:
        mod = importlib.import_module(mod_name)
    except ModuleNotFoundError as e:
        skipped = True
        continue
    except Exception as e:
        failed += 1
        continue

    # Only process if mod was successfully imported
    # Collect bare test functions
    for name in dir(mod):
        if name.startswith('test_'):
            func = getattr(mod, name)
            if callable(func) and func.__code__.co_argcount == 0:
                collected += 1
                try:
                    func()
                except Exception as e:
                    failed += 1

    # Collect unittest.TestCase subclasses
    for name in dir(mod):
        cls = getattr(mod, name)
        if isinstance(cls, type) and issubclass(cls, unittest.TestCase) and cls is not unittest.TestCase:
            suite = unittest.TestLoader().loadTestsFromTestCase(cls)
            collected += suite.countTestCases()
            result = unittest.TextTestRunner(verbosity=0).run(suite)
            if not result.wasSuccessful():
                failed += 1

if failed > 0:
    print("FAILED")
elif collected == 0 and skipped:
    print("SKIPPED")
elif collected == 0:
    print("FAILED")
else:
    print("PASSED")
"""
        try:
            result = subprocess.run([self.python_executable, '-c', script], cwd=workdir, env=env, capture_output=True, text=True, timeout=self.timeout_s)
            duration = time.time() - start
            output = result.stdout.strip()
            if output == "PASSED":
                return GateResult(name='tests', status=PASSED, method='stdlib', detail='All tests passed', duration_s=duration)
            elif output == "SKIPPED":
                return GateResult(name='tests', status=SKIPPED, method='stdlib', detail='Missing dependencies', duration_s=duration)
            else:
                return GateResult(name='tests', status=FAILED, method='stdlib', detail='Tests failed or not collected', duration_s=duration)
        except Exception as e:
            return GateResult(name='tests', status=FAILED, method='stdlib', detail=f'Execution error: {e}', duration_s=time.time()-start)

    def _gate_telemetry(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        py_files = [p for p in authored.keys() if p.endswith('.py')]
        if not py_files:
            return GateResult(name='telemetry', status=FAILED, method='ast', detail='No Python files', duration_s=time.time()-start)

        has_import = False
        has_call = False

        tracer_methods = {'start_as_current_span', 'start_span', 'get_tracer', 'get_tracer_provider', 'set_tracer_provider', 'get_meter'}

        for path in py_files:
            content = authored[path]
            try:
                tree = ast.parse(content)
            except SyntaxError:
                continue

            for node in ast.walk(tree):
                # Check for import opentelemetry
                if isinstance(node, ast.Import):
                    for alias in node.names:
                        if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                            has_import = True
                elif isinstance(node, ast.ImportFrom):
                    if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                        has_import = True

                # Check for calls
                if isinstance(node, ast.Call):
                    func = node.func
                    if isinstance(func, ast.Attribute):
                        if func.attr in tracer_methods:
                            has_call = True
                    elif isinstance(func, ast.Name):
                        if func.id in tracer_methods:
                            has_call = True

        duration = time.time() - start
        if has_import and has_call:
            return GateResult(name='telemetry', status=PASSED, method='ast', detail='OpenTelemetry usage detected', duration_s=duration)
        else:
            detail = []
            if not has_import:
                detail.append('No OpenTelemetry import')
            if not has_call:
                detail.append('No tracer/span calls')
            return GateResult(name='telemetry', status=FAILED, method='ast', detail='; '.join(detail), duration_s=duration)

